class SendMessageDialogController{constructor($scope,$mdDialog,DispatchData,toastrService,selectedCourierId){this.$scope=$scope;this.$mdDialog=$mdDialog;this.DispatchData=DispatchData;this.toastrService=toastrService;this.message="";this.searchText="";this.getCurrentCourier(selectedCourierId).then(_=>console.log("Courier method completed!"))}async getCurrentCourier(selectedCourierId){try{if(selectedCourierId===undefined){return}this.selectedItem=await this.DispatchData.getSingleCourier(selectedCourierId)}catch(error){console.log("Error",error)}}async querySearch(searchTerm){try{const url="/courier/AllActiveSearch";return await this.DispatchData.autocompleteSearch(searchTerm,url)}catch(error){this.toastrService.showErrorToast(error.message)}}async submit(message,selectedCourier){try{console.log("Message",message);console.log("Courier",selectedCourier);await this.DispatchData.sendSMS(selectedCourier.courierId,ContactID,FirstName,message);this.toastrService.showSuccessToast("Message Sent!")}catch(error){this.toastrService.showErrorToast(error.message)}finally{this.$mdDialog.hide()}}cancel(){this.$mdDialog.cancel()}}